import math

def prime_factorization(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def calculate_an(n):
    return 6**n + 2**n + 3**n - 1

all_prime_factors = set()
A = {}

for n in range(1, 16):
    a_n = calculate_an(n)
    A[n] = a_n
    factors = prime_factorization(a_n)
    all_prime_factors.update(factors)

print("Calculated A values:", A)
print("All prime factors found:", sorted(list(all_prime_factors)))

